import { useIntl } from 'react-intl';

import { BasicContainer, CountryFlag, NoDataYet, Tag } from 'components';
import { FILTER_MODAL_NAME } from 'components/Filter';
import { CalendarClock } from 'components/icon';
import { useLastDataRefresh } from 'contexts';
import { useDataRefreshForTab } from 'contexts/DataRefreshModal/useDataRefreshForTab';
import { useScopedModal } from 'contexts/Modal/ModalContext';
import { usePageFilterApplied } from 'hooks';
import { StyledTooltip } from 'shared/Styles';

import { RESOURCE_ALLOCATION_MEDIA_PAGE_NAME } from '../../ResourceAllocationMedia';
import { DeepDiveView, SummaryView } from './components';
import { useOverviewDataSource } from './hooks/useOverviewDataSource';
import { StyledEmptyState, StyledOverviewContainer } from './Overview.styles';
import { hasOverviewData } from './utils/hasOverviewData';

export interface OverviewProps {
  dataTestId?: string;
}

export const Overview = ({ dataTestId }: OverviewProps) => {
  useDataRefreshForTab('Resource Allocation - Overview');
  const { formatMessage } = useIntl();
  const { open: openFilterModal } = useScopedModal(FILTER_MODAL_NAME);
  const { isGlobalZone, applied } = usePageFilterApplied(
    RESOURCE_ALLOCATION_MEDIA_PAGE_NAME,
  );
  const { lastDataRefreshKpisFormated } = useLastDataRefresh();
  const lastDataRefresh = lastDataRefreshKpisFormated?.media;

  const { dataSource, isReady, isBreakdownViewer, activeDeepDiveSubfilter } =
    useOverviewDataSource();

  const loading =
    dataSource.charts.loading ||
    dataSource.table.loading ||
    dataSource.ranking.loading;
  const hasData = hasOverviewData(dataSource);

  const emptyStateTitle = formatMessage({
    id: 'ConnectionsCreativity.ResourceAllocationMedia.Overview.emptyState.title',
  });
  const emptyStateDescription = formatMessage({
    id: 'ConnectionsCreativity.ResourceAllocationMedia.Overview.emptyState.description',
  });
  const selectCountryLabel = formatMessage({
    id: 'ConnectionsCreativity.ResourceAllocationMedia.Overview.selectACountry',
  });

  const countrySelected = applied?.country;

  const showSelectCountryEmptyState =
    isReady && !loading && !isGlobalZone && !countrySelected;
  const showNoDataEmptyState =
    isReady &&
    !loading &&
    !isGlobalZone &&
    Boolean(countrySelected) &&
    !hasData;
  const showTabContent =
    isReady &&
    !loading &&
    !showSelectCountryEmptyState &&
    !showNoDataEmptyState;

  const renderFullPageEmptyState = (withAction: boolean) => (
    <StyledEmptyState
      data-testid={
        dataTestId ? `${dataTestId}-overview-empty-state` : undefined
      }
      style={{ padding: '64px 24px' }}
    >
      <NoDataYet
        title={emptyStateTitle}
        description={emptyStateDescription}
        illustration="noDataAvailable"
        size="auto"
        dataTestId={dataTestId ? `${dataTestId}-overview` : undefined}
        action={
          withAction
            ? { label: selectCountryLabel, onClick: openFilterModal }
            : undefined
        }
      />
    </StyledEmptyState>
  );

  if (!isReady) {
    return null;
  }

  return (
    <BasicContainer
      dataTestId={dataTestId}
      header={{
        title: formatMessage({
          id: 'ConnectionsCreativity.ResourceAllocationMedia.Overview.title',
        }),
        tooltip: (
          <StyledTooltip
            size="small"
            data-testid={dataTestId ? `${dataTestId}-tooltip` : undefined}
          >
            {formatMessage({
              id: 'ConnectionsCreativity.ResourceAllocationMedia.Overview.tooltip',
            })}
          </StyledTooltip>
        ),
        titleSize: 'H2',
        rightContent: <CountryFlag dataTestId={dataTestId} />,
        bottomTag: lastDataRefresh ? (
          <Tag
            Icon={CalendarClock}
            text={`: ${lastDataRefresh}`}
            dataTestId={
              dataTestId ? `${dataTestId}-last-data-refresh-tag` : undefined
            }
          />
        ) : null,
      }}
      layout={{
        border: 'small',
        shadow: 'small',
        headerPadding: 'small',
        bodyPadding: true,
      }}
    >
      {showSelectCountryEmptyState && renderFullPageEmptyState(true)}
      {showNoDataEmptyState && renderFullPageEmptyState(false)}

      {(loading || showTabContent) && (
        <StyledOverviewContainer
          data-testid={dataTestId ? `${dataTestId}-container` : undefined}
        >
          <SummaryView charts={dataSource.charts} dataTestId={dataTestId} />
          <DeepDiveView
            dataSource={dataSource}
            activeDeepDiveSubfilter={activeDeepDiveSubfilter}
            isBreakdownViewer={isBreakdownViewer}
            data-testid="deep-dive-view"
            dataTestId={dataTestId}
          />
        </StyledOverviewContainer>
      )}
    </BasicContainer>
  );
};
